      <div class="cols2"><div class="glass panel"><div class="panel-h"><h3>Interações no ano</h3><small>soma dos meses</small></div>${hBars([['Curtidas', tot('likes'), '#ff7a3d'], ['Comentários', tot('comments'), '#ffb37a'], ['Compartilhamentos', tot('shares'), '#9fb8ff'], ['Salvamentos', tot('saves'), '#3fd08f']])}</div>
        <div class="glass panel"><div class="panel-h"><h3>Posts por formato</h3><small>${P.length} no ano</small></div>${fmtBox(P)}</div></div>
