  const emptyState = (clientId, mode) => mode === 'portal' ? emptyBox('chart', 'Nenhum relatório publicado ainda', 'O primeiro relatório aparece aqui assim que a FX fechar o mês.') : emptyBox('chart', 'Sem métricas lançadas', 'Lance os números do Instagram de um mês para gerar gráficos e o relatório.', `<button class="pill orange" data-add-metrics="${clientId}">${icon('plus')}Lançar métricas</button>`);
  // PDF: monta uma versão clara do relatório e abre a janela de impressão ("Salvar como PDF")
