    const monthTable = `<div class="glass panel"><div class="panel-h"><h3>Mês a mês</h3><small>Instagram · ${list.length} ${list.length > 1 ? 'meses' : 'mês'}</small></div><div class="tbl-wrap"><table class="mtable"><thead><tr><th>Mês</th>${METRICS.map(x => `<th class="r">${x[1]}</th>`).join('')}</tr></thead><tbody>${list.slice().reverse().map(x => `<tr class="${x.month === sel ? 'cur' : ''}"><td><b>${mLabel(x.month)}</b></td>${METRICS.map(k => `<td class="r">${fmtMetric(k[0], x[k[0]])}</td>`).join('')}</tr>`).join('')}</tbody></table></div></div>`;
