  const leadCard = l => { const q = qualify(l), p = l.package ? packById(l.package) : null; return `<button class="kcard" draggable="true" data-lead="${l.id}"><span class="row"><b>${esc(l.name)}</b><span class="tag dot ${q.level[1]}">${q.level[0]} ${q.score}</span></span><small>${esc(l.company)}${l.segment ? ' · ' + esc(segName(l.segment)) : ''}</small><span class="row">${trackTag(l)}<span class="tag">${l.track === 'sistema' ? (l.modules || []).length + ' áreas' : p ? esc(p.name) : 'sem pacote'}</span></span><span class="row"><small>${icon('link', 'style="width:12px;height:12px;vertical-align:-1px"')} ${esc(linkById(l.link).name)}</small><small>${ago(l.created)}</small></span></button>`; };
